mapper.update:
UPDATE notes
SET like_count = GREATEST(like_count + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

UPDATE notes
SET comment_count = GREATEST(comment_count + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

UPDATE notes
SET collect_count = GREATEST(collect_count + #{delta}, 0), updated_at = CURRENT_TIMESTAMP
WHERE note_id = #{noteId}

